<script setup lang="ts">
import { computed, reactive, watch } from 'vue';
import { Activity, ArrowRight, Check, Clock3, Cpu, FileText, Gauge, Play, Plus, Server, Settings2, Square, Zap } from 'lucide-vue-next';
import TrendChart from './TrendChart.vue';
import EndpointSelect from './EndpointSelect.vue';
import { phaseName, summarize, loadReportSummary, type MeasurementReport, type LoadResult, type LoadConfig, type EndpointConfig } from './engine';
import { LOAD_DEFAULTS, LOAD_LIMITS } from './load-goal';
import { loadOperations, loadOperationName } from './load-operations';
const props = defineProps<{ endpoints: EndpointConfig[]; result: LoadResult | null; resultConfig?: LoadConfig; busy: boolean; running: boolean; reportAvailable: boolean; report?: MeasurementReport }>();
const emit = defineEmits<{ start: [config: LoadConfig]; stop: []; increase: []; report: []; export: [] }>();
const config = reactive<LoadConfig>({ ...props.resultConfig, ...LOAD_DEFAULTS, maxConcurrency:LOAD_DEFAULTS.concurrency+1000, rps:props.resultConfig?.rps ?? 0, endpointId:props.resultConfig?.endpointId || 'delivery-availability' });
const operations = computed(()=>loadOperations(props.endpoints));
watch(operations, items=>{if(!items.some(item=>item.id===config.endpointId))config.endpointId=items[0]?.id || '';},{immediate:true});
watch(()=>config.concurrency,(target,previous)=>{
  if(Number.isInteger(target) && target>=LOAD_LIMITS.minConcurrency && target<=LOAD_LIMITS.maxConcurrency && (config.maxConcurrency===previous+1000 || (config.maxConcurrency || 0)<target+600))config.maxConcurrency=target+1000;
});
const reportGoal=computed(()=>props.report?loadReportSummary(props.report).goal:undefined);
const validParameters=computed(()=>Number.isInteger(config.concurrency) && config.concurrency>=LOAD_LIMITS.minConcurrency && config.concurrency<=LOAD_LIMITS.maxConcurrency && Number.isInteger(config.maxConcurrency) && config.maxConcurrency!>=config.concurrency+600 && config.maxConcurrency!<=LOAD_LIMITS.maxSafetyConcurrency && Number.isInteger(config.duration) && config.duration>=LOAD_LIMITS.minDuration && config.duration<=LOAD_LIMITS.maxDuration && Number.isInteger(config.rps) && config.rps>=0 && config.rps<=50000);
const chartConfig = computed(()=>props.result && props.resultConfig ? props.resultConfig : config);
const stats = computed(()=>summarize(props.result?.samples || [],props.result?.elapsedMs || 0));
const lastFrame = computed(()=>props.result?.frames.at(-1));
const endpoint = computed(()=>props.endpoints.find(e=>e.id===chartConfig.value.endpointId));
const operationName = computed(()=>loadOperationName(props.endpoints,chartConfig.value.endpointId));
const observedPeak = computed(()=>Math.max(0,...(props.result?.frames.filter(frame=>(frame.windowSeconds || 0)>0 && (frame.completed || 0)>0).map(frame=>frame.concurrency) || [])));
const stageNames = ['起步','递增','目标','探索','稳定'];
const recentEvents = computed(()=>[...(props.result?.events || [])].reverse().slice(0,4));
const number = (value:number,digits=0)=>value.toLocaleString('zh-CN',{maximumFractionDigits:digits});
const canIncrease = computed(()=>props.running && (props.result?.level || 0)<5);
</script>
<template>
  <div class="pressure-workspace">
    <section class="page-heading"><div><div class="eyebrow">CONCURRENCY TEST / OBSERVABILITY</div><h1>并发测试，观察业务操作的承载表现。</h1><p>预期目标用于验收比较，安全上限用于限制加压；达到目标后继续探索。</p></div><button class="secondary" :disabled="busy || !reportAvailable" @click="emit('export')"><FileText :size="16"/>导出最近报告</button></section>
    <div class="context-strip"><span><span class="status-dot"/>智慧校园</span><span>{{operationName}}</span><span class="context-right">{{operations.length}} 项业务操作 · {{running?'测试进行中':result?'本轮记录已保存':'等待手动启动'}}</span></div>
    <section class="metrics" aria-label="测试指标">
      <article><div class="metric-label">当前并发负载<Cpu :size="17"/></div><div class="metric-value">{{result?number(lastFrame?.concurrency || 0):'—'}}<span>并发</span></div><div class="metric-foot"><span class="status-dot"/>{{result?phaseName(result.phase):'等待启动'}}<small>预期 {{number(chartConfig.concurrency)}}</small></div></article>
      <article><div class="metric-label">实时吞吐量<Zap :size="17"/></div><div class="metric-value">{{result?number(lastFrame?.rps || 0,1):'—'}}<span>req/s</span></div><div class="metric-foot">{{chartConfig.rps?`上限 ${number(chartConfig.rps)} req/s`:'按并发与耗时计算'}}<small>当前窗口</small></div></article>
      <article><div class="metric-label">累计完成请求<Check :size="17"/></div><div class="metric-value">{{result?number(stats.count):'—'}}<span>次</span></div><div class="metric-foot"><span class="status-dot"/>{{stats.count?number(stats.successRate,1)+'% 通过率':'准备采样'}}<small>本轮累计</small></div></article>
      <article><div class="metric-label">P95 响应延迟<Activity :size="17"/></div><div class="metric-value">{{lastFrame?.p95?number(lastFrame.p95,1):'—'}}<span>ms</span></div><div class="metric-foot">{{lastFrame?.p50?`P50 ${number(lastFrame.p50,1)} ms`:'等待首个窗口'}}<small>当前窗口</small></div></article>
    </section>
    <div v-if="reportAvailable && !busy" class="load-report-entry" :class="{failed:reportGoal?.verdict==='failed',insufficient:reportGoal?.verdict==='insufficient'}"><div><FileText :size="18"/><span>{{reportGoal?.verdictLabel || '最近一轮并发测试报告已保存'}} · 预期 {{reportGoal?.targetConcurrency || '—'}} / {{reportGoal?.capacityMode?'稳定承载':'峰值'}} {{reportGoal?.capacityMode ? (reportGoal.capacityConcurrency || '待确认') : reportGoal?.peakConcurrency || 0}}</span></div><button class="secondary" @click="emit('report')">查看并发测试报告<ArrowRight :size="14"/></button></div>
    <div class="pressure-layout">
      <section class="panel pressure-config"><div class="panel-heading"><div><h2><Settings2 :size="18"/>负载配置</h2><p>定义本轮测试的目标与节奏</p></div></div><fieldset :disabled="busy"><div class="endpoint-field"><span>测试业务操作</span><EndpointSelect v-model="config.endpointId" :endpoints="operations" business :disabled="busy"/></div><label>预期并发目标<input v-model.number="config.concurrency" aria-label="预期并发目标" type="number" :min="LOAD_LIMITS.minConcurrency" :max="LOAD_LIMITS.maxConcurrency"/></label><label>安全加压上限<input v-model.number="config.maxConcurrency" aria-label="安全加压上限" type="number" :min="config.concurrency+600" :max="LOAD_LIMITS.maxSafetyConcurrency"/></label><div class="input-pair"><label>测试时长（秒）<input v-model.number="config.duration" aria-label="持续时长" type="number" min="10" max="120"/></label><label>吞吐上限（req/s）<input v-model.number="config.rps" aria-label="吞吐上限" type="number" min="0" max="50000"/></label></div></fieldset><button class="primary full" aria-label="开始并发测试" :disabled="busy || !operations.length || !validParameters" @click="emit('start',{...config})"><Play :size="15"/>启动并发测试</button><p v-if="!validParameters" class="config-limit" role="alert">目标须为5–10,000；安全上限须在目标＋600至20,000之间；时长10–120秒，吞吐上限0–50,000。</p><p v-if="!operations.length" class="config-limit">先在API测试中生成用例，再选择本轮测试的业务操作。</p><div class="strategy-card"><span class="tiny-tag">STEP LOAD</span><h3>自动递增 · 超目标探索</h3><div class="strategy-steps"><i v-for="level in 5" :key="level" :style="{height:`${10+level*7}px`}"/></div><p>预热 → 递增 → 达到目标 → 超目标探索 → 稳定观察。安全上限不是测试结果；以有效窗口核对成功率和延迟。</p></div><div class="config-limit"></div><button v-if="running" class="secondary full" aria-label="停止并发测试" @click="emit('stop')"><Square :size="13"/>停止测试</button><div class="config-system"><Server :size="15"/><div>智慧校园<code>{{operationName}}</code></div></div></section>
      <div class="pressure-observation">
        <section class="load-goal-strip" aria-label="目标与观测结果"><span>预期目标 <b>{{number(chartConfig.concurrency)}}</b></span><span>安全上限 <b>{{number(chartConfig.maxConcurrency || chartConfig.concurrency)}}</b></span><span>观测峰值 <b>{{result?number(observedPeak):'—'}}</b></span><span>稳定承载 <b>{{reportGoal?.capacityMode && reportGoal.executionComplete && reportGoal.capacityConcurrency ? number(reportGoal.capacityConcurrency) : result?'待确认':'—'}}</b></span></section>
        <section class="panel load-chart-panel"><div class="panel-heading"><div><h2><Gauge :size="19"/>负载与吞吐</h2><p>目标线只作比较，超过目标后继续观察业务承载</p></div><div class="pressure-main-actions"><span class="phase-badge" :class="{running}"><span class="status-dot"/>{{result?phaseName(result.phase):'等待启动'}}</span><button class="boost-button" :disabled="!canIncrease" @click="emit('increase')"><Plus :size="17"/>加压一级</button></div></div><div class="pressure-stage"><div><small>当前负载阶段</small><strong>第 <b>{{result?.level || 0}}</b> / 5 级</strong></div><div class="stage-stair"><span v-for="level in 5" :key="level" :class="{active:(result?.level || 0)>=level}"><i :style="{height:`${9+level*6}px`}"/><small>{{stageNames[level-1]}}</small></span></div><div class="stage-time"><strong>{{number((result?.elapsedMs || 0)/1000,1)}}<small> / {{chartConfig.duration}} s</small></strong><span>{{result?.status==='completed'?'本轮已完成':result?.status==='stopped'?'保留停止时曲线':result?'自动加压与稳定观察':'等待手动启动'}}</span></div></div><TrendChart kind="load" show-target :frames="result?.frames || []" :events="result?.events || []" :duration="chartConfig.duration" :concurrency="chartConfig.concurrency" :load-max="chartConfig.maxConcurrency" :rps="chartConfig.rps" label="本轮负载与吞吐趋势"/><div class="chart-footer"><span class="chart-legend"><i/>并发负载 <i class="amber-line"/>实时吞吐量</span><span>左轴：并发 · 右轴：req/s · ＋：手动加压</span></div></section>
        <section class="panel latency-live-panel"><div class="panel-heading"><div><h2><Activity :size="18"/>响应延迟趋势</h2><p>随负载升高与加压事件变化的窗口分位数</p></div><div class="inline-percentiles"><span>P50 <b>{{lastFrame?.p50?number(lastFrame.p50,1):'—'}}</b></span><span>P95 <b>{{lastFrame?.p95?number(lastFrame.p95,1):'—'}}</b></span><span>P99 <b>{{lastFrame?.p99?number(lastFrame.p99,1):'—'}}</b><small> ms</small></span></div></div><TrendChart :frames="result?.frames || []" :duration="chartConfig.duration" :latency-max="endpoint?.budget || 500" compact label="本轮响应延迟趋势"/><div class="chart-footer"><span class="chart-legend"><i/>P50 <i class="light-line"/>P95</span><span>响应预算 {{endpoint?.budget || 500}} ms</span></div></section>
        <section class="event-strip load-event-list" aria-label="加压事件"><span><Clock3 :size="14"/>加压事件</span><p v-if="!recentEvents.length">计划升档和手动加压将在这里留痕</p><span v-for="event in recentEvents" :key="event.id" class="event-chip" :class="{manual:event.type==='manual'}">{{event.second.toFixed(1)}} s · {{event.type==='manual'?'手动':'计划'}} → {{event.level}} 级</span></section>
      </div>
    </div>
  </div>
</template>
<style scoped>
.load-goal-strip{display:flex;flex-wrap:wrap;gap:10px 22px;padding:13px 18px;border:1px solid #dce7d5;background:#f4f8ef;border-radius:9px;font-size:11px;color:#708567}.load-goal-strip b{margin-left:5px;font:16px var(--mono);color:#356444}
.endpoint-field { min-width:0; margin-top:4px; font-size:11px; color:#6e825f; }
