.primary,.secondary { padding:11px 16px; border-radius:7px; font-size:12px; min-height:38px; }.full { width:100%; }.metrics { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:15px; margin-bottom:18px; }.metrics article { background:white; border:1px solid var(--line); border-radius:10px; padding:14px 21px 12px; box-shadow:0 3px 8px #35433102; }.metric-label { font-size:11px; color:#6e8068; display:flex; align-items:center; justify-content:space-between; }.metric-label svg { color:#93a18d; }.metric-value { font:500 32px var(--mono); letter-spacing:-1px; margin:8px 0 10px; color:#294b35; }.metric-value > span { font-size:13px; letter-spacing:0; color:#93a088; margin-left:9px; font-weight:400; }.metric-foot { font-size:9px; color:#8e9a86; display:flex; align-items:center; gap:6px; white-space:nowrap; }.metric-foot small { margin-left:auto; font-size:8px; color:#8b9b80; }
.panel { border-radius:10px; }.panel-heading { padding:20px 24px; align-items:center; }.panel-heading h2 { display:flex; align-items:center; gap:8px; font-size:15px; color:#355b40; font-weight:500; }.panel-heading p { font-size:11px; color:#93a087; margin-top:7px; line-height:1.7; }.load-report-entry { display:flex; align-items:center; justify-content:space-between; gap:15px; padding:14px 18px; margin-bottom:18px; background:#eef5e7; border:1px solid #dbe7ce; border-radius:10px; font-size:12px; color:#658251; }.load-report-entry > div { display:flex; align-items:center; gap:9px; }
.pressure-layout { display:grid; grid-template-columns:270px minmax(0,1fr); gap:20px; }.pressure-config { padding:0 20px 20px; align-self:start; }.pressure-config .panel-heading { padding-inline:0; }.pressure-config fieldset { border:0; padding:0; margin:0; }.pressure-config label { display:flex; flex-direction:column; gap:8px; font-size:11px; color:#6e825f; margin:4px 0 17px; }.pressure-config input,.pressure-config select { width:100%; font-size:12px; padding:10px; border-color:#dfe7df; border-radius:7px; color:#33483d; }.input-pair { display:grid; grid-template-columns:1fr 1fr; gap:10px; }.input-pair label { font-size:10px; }.pressure-config .primary { margin-top:1px; }.pressure-config > .secondary { margin-top:10px; }.boost-button { border:1px solid #d4bc78; border-radius:7px; background:#f7edce; color:#8c691c; padding:9px 13px; min-height:38px; font-size:11px; }.boost-button:hover:not(:disabled) { background:#f0dfa8; border-color:#c5a34e; }.strategy-card { border:1px solid #e2e9d9; background:#f6f9f1; border-radius:8px; padding:14px; margin:18px 0 16px; }.tiny-tag { display:none; }.strategy-card h3 { font-size:12px; font-weight:500; color:#617c50; }.strategy-card p { font-size:10px; color:#8b9c7c; line-height:1.8; }.strategy-steps { display:flex; align-items:flex-end; gap:6px; margin:12px 0 11px; height:35px; }.strategy-steps i { background:#b4c9a3; flex:1; border-radius:3px 3px 0 0; }.strategy-steps i:nth-child(2) { background:#9fbb8b; }.strategy-steps i:nth-child(3) { background:#81a971; }.strategy-steps i:nth-child(4) { background:#5e8e59; }.strategy-steps i:nth-child(5) { background:#3a6b45; }.config-limit { margin-top:8px; font-size:10px; line-height:1.8; color:#9ca88f; }.config-system { display:flex; align-items:center; gap:10px; padding-top:18px; margin-top:20px; border-top:1px solid #e3eada; font-size:11px; color:#7c9270; overflow:hidden; }.config-system > div { min-width:0; }.config-system code { display:block; font-size:9px; margin-top:5px; color:#9cab8e; overflow:hidden; white-space:nowrap; text-overflow:ellipsis; }
